'use strict';
let paintFilters={query:'',year:'',color:'all',kind:'all'};
function paintEdition(){return document.documentElement?.dataset.paintEdition==='ledger'?'ledger':'swatches';}
function paintYears(e){return e.from===e.to?String(e.from):`${e.from}–${e.to}`;}
function paintSources(e){return `<details class="paint-details"><summary>Sources & matching notes<span class="paint-sr"> for ${esc(e.title)}</span></summary><div><p>${esc(e.caveat)}</p><ul>${e.sources.map(s=>`<li><a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.label)} <span aria-hidden="true">↗</span></a><small>${esc(s.access)}</small></li>`).join('')}</ul><h4>Before choosing this paint</h4><p>${esc(e.next)}</p></div></details>`;}
function paintCards(entries){return `<div class="paint-card-grid">${entries.map(e=>`<article class="paint-card paint-${e.color}" aria-labelledby="paint-${e.id}"><div class="paint-card-heading"><span class="paint-source-type ${e.kind==='document'?'paint-document':''}">${esc(e.label)}</span><span>${paintYears(e)}</span></div><p class="paint-brand">${esc(e.brand)}</p><h3 id="paint-${e.id}">${esc(e.title)}</h3><p class="paint-code">${esc(e.code)}</p><p class="paint-part">${esc(e.part)}</p><p class="paint-description">${esc(e.summary)}</p>${paintSources(e)}</article>`).join('')}</div>`;}
function paintLedger(entries){return `<div class="paint-ledger-table"><table><caption class="paint-sr">Paint references and their claimed years. Open sources to see qualifications.</caption><thead><tr><th scope="col">Reference / code</th><th scope="col">Claimed years</th><th scope="col">Evidence & sources</th></tr></thead><tbody>${entries.map(e=>`<tr><td><span class="paint-source-dot paint-${e.color}" aria-hidden="true"></span><h3>${esc(e.title)}</h3><p class="paint-brand">${esc(e.brand)}</p><p class="paint-code">${esc(e.code)}</p><small>${esc(e.part)}</small></td><td>${paintYears(e)}</td><td><span class="paint-source-type ${e.kind==='document'?'paint-document':''}">${esc(e.label)}</span><p class="paint-description">${esc(e.summary)}</p>${paintSources(e)}</td></tr>`).join('')}</tbody></table></div>`;}
function paintResults(){const entries=PaintReferences.filter(paintFilters);return `<p class="paint-result-count" role="status">${entries.length} of ${PaintReferences.entries.length} references${paintFilters.year?' · source claims include '+esc(paintFilters.year):''}</p>${entries.length?(paintEdition()==='ledger'?paintLedger(entries):paintCards(entries)):'<div class="paint-empty"><h3>No references match yet.</h3><p>Try another year or color, or clear the filters. A missing result is a research gap.</p><button class="button secondary" data-paint-reset>Clear filters</button></div>'}`;}
function paintReferenceView(){
 const ledger=paintEdition()==='ledger';
 return `${isDesignPreview()?`<div class="design-review"><div><span class="design-review-dot" aria-hidden="true"></span><b>${yearbookEdition()==='sheets'?'Year sheets':yearbookEdition()==='gallery'?'Year gallery':ledger?'Reference ledger':'Swatchbook'}</b><span>Paint reference preview · read only</span></div><a href="${LIVE_GARAGE}" target="_blank" rel="noopener">Open live garage ↗</a></div>`:''}<div class="paint-library ${ledger?'paint-ledger':'paint-swatches'}"><header class="paint-intro"><div><p class="paint-caption">The restoration reference shelf</p><h1>Paint codes & colors.</h1><p>Find the right finish.<br>Keep the evidence with the code.</p><span>Historical formulas, modern matches and open questions gathered from the Ski-Doo community. Every entry links back to its source.</span></div>${!ledger?'<div class="paint-family-chips" aria-label="Illustrative color families, not matched paint samples"><div><b>Yellow</b><small>Body & hood leads</small></div><div><b>Red</b><small>Detail color leads</small></div><div><b>Black</b><small>Finish leads</small></div></div>':'<aside class="paint-evidence-key"><h2>Read the evidence</h2><p><b>Archived formula</b>A recipe visible in a historical document.</p><p><b>Reported match</b>A member’s example or compiled lead.</p><small>Neither verifies a paint for your sled.</small></aside>'}</header><section class="paint-project-note" aria-labelledby="paint-project-note-title"><span aria-hidden="true">◇</span><div><h2 id="paint-project-note-title">Your early sled’s year is still unconfirmed.</h2><p>These are research references. Check the chassis year, model and part before choosing a finish. Browsing a code does not change your restoration record.</p></div><button class="paint-text-button" data-guide-sled="early">Review identification</button></section>${paintYearbook()}<section aria-labelledby="paint-browse-title"><div class="paint-browse-heading"><h2 id="paint-browse-title">Browse the references</h2><p>Years are source claims, not verified fitment.</p></div><form class="paint-filters" role="search" aria-label="Filter paint references"><label>Search codes or brands<input id="paint-search" type="search" placeholder="e.g. Imron, Marigold, 79668" value="${esc(paintFilters.query)}"></label><label>Claimed year<select id="paint-year"><option value="">All years</option>${Array.from({length:11},(_,i)=>1960+i).map(y=>`<option value="${y}"${paintFilters.year===String(y)?' selected':''}>${y}</option>`).join('')}</select></label><label>Color family<select id="paint-color">${[['all','All colors'],['yellow','Yellow'],['red','Red'],['black','Black']].map(([value,label])=>`<option value="${value}"${paintFilters.color===value?' selected':''}>${label}</option>`).join('')}</select></label><label>Evidence<select id="paint-kind">${[['all','All evidence'],['document','Archived document'],['community','Community & compiled']].map(([value,label])=>`<option value="${value}"${paintFilters.kind===value?' selected':''}>${label}</option>`).join('')}</select></label><button type="button" class="paint-text-button" data-paint-reset>Clear filters</button></form><div id="paint-results">${paintResults()}</div></section><section class="paint-open-questions" aria-labelledby="paint-questions-title"><div><p class="paint-caption">Keep the questions visible</p><h2 id="paint-questions-title">What still needs checking.</h2></div><div><article><h3>Was 1964 a different yellow?</h3><p>The archived chart groups 1964–1970, while a public discussion describes 1964 as darker than later yellows. Keep both sources until original paint or factory evidence resolves it.</p><a href="${PaintReferences.conflict.url}" target="_blank" rel="noopener">Read the year disagreement ↗</a></article><article><h3>What is the right engine gray?</h3><p>The early-year discussion asks for gray, but this pass did not establish a reliable code or component match. No gray formula is recorded here.</p></article><article><h3>What matches these actual sleds?</h3><p>Identify the chassis and component, preserve a protected original-paint sample, then have a supplier check a physical test sample and the current product system.</p></article></div></section><p class="paint-library-note">First research pass · October 19, 2026. This is a growing reference, not an exhaustive group archive. Color chips indicate families only; screens cannot verify a paint match. Facebook links may require sign-in or group membership. Original member photos stay on Facebook. Follow the chosen product’s current technical and safety data.</p></div>`;
}
function updatePaintResults(){const target=document.querySelector('#paint-results');if(target)target.innerHTML=paintResults();}
document.addEventListener('input',event=>{if(event.target.id!=='paint-search')return;paintFilters.query=event.target.value;updatePaintResults();});
document.addEventListener('change',event=>{const key={'paint-year':'year','paint-color':'color','paint-kind':'kind'}[event.target.id];if(key){paintFilters[key]=event.target.value;updatePaintResults();}});
document.addEventListener('submit',event=>{if(event.target.matches?.('.paint-filters'))event.preventDefault();});
document.addEventListener('click',event=>{const button=event.target.closest('button[data-paint-reset]');if(!button?.hasAttribute('data-paint-reset'))return;paintFilters={query:'',year:'',color:'all',kind:'all'};render('paint');document.querySelector('#paint-search')?.focus({preventScroll:true});});
